const items = $input.all();

const excludeKeywords = [
  'graphic design', 'logo design', 'wordpress',
  'data entry', 'virtual assistant', 'content writing',
  'seo', 'video editing', 'social media'
];

const acceptEntry = false;
const acceptIntermediate = true;
const acceptExpert = true;

const minFixedBudget = 100;      // Minimum for fixed jobs
const minHourlyRate = 15;        // Minimum hourly rate

const filteredItems = [];

for (const item of items) {

  const title = (item.json.title || '').toLowerCase();
  const description = (item.json.description || '').toLowerCase();
  const experienceLevel = (item.json.experienceLevel || '').toLowerCase();
  const budgetRaw = (item.json.budget || '').trim();
  const jobType = item.json.jobType;

  let shouldKeep = true;

  // 1️⃣ Experience filter
  if (experienceLevel.includes('entry') && !acceptEntry) shouldKeep = false;
  if (experienceLevel.includes('intermediate') && !acceptIntermediate) shouldKeep = false;
  if (experienceLevel.includes('expert') && !acceptExpert) shouldKeep = false;

  // 2️⃣ Keyword filter
  if (shouldKeep) {
    for (const keyword of excludeKeywords) {
      if (title.includes(keyword) || description.includes(keyword)) {
        shouldKeep = false;
        break;
      }
    }
  }

  // 3️⃣ Budget filter (proper parsing)
  if (shouldKeep && budgetRaw && budgetRaw !== 'N/A') {

    // FIXED PRICE: "$375.00"
    if (jobType === 'Fixed' && budgetRaw.startsWith('$')) {
      const value = parseFloat(budgetRaw.replace(/[^0-9.]/g, ''));
      if (value < minFixedBudget) {
        shouldKeep = false;
      }
    }

    // HOURLY RANGE: "12 - 35"
    else if (jobType === 'Hourly' && budgetRaw.includes('-')) {
      const parts = budgetRaw.split('-').map(p => parseFloat(p.trim()));
      const maxRate = parts[1] || parts[0];

      if (maxRate < minHourlyRate) {
        shouldKeep = false;
      }
    }
  }

  if (shouldKeep) {
    filteredItems.push(item);
  }
}

return filteredItems;

